.grid-scroll { width: 100%; overflow-x: auto; scrollbar-color: #cfd9d0 transparent; scrollbar-width: thin; }
.grid-inner { min-width: 1140px; padding: 12px 15px 11px; }
.desktop-grid { width: 100%; display: flex; flex-direction: column; gap: 4px; }
.desktop-grid-head, .desktop-city-row { display: grid; grid-template-columns: 206px repeat(24, minmax(34px, 1fr)) 28px; column-gap: 3px; align-items: stretch; }
