.ref-badge { display: inline-flex; align-items: center; justify-content: center; padding: 2px 4px; border: 1px solid #cde5d0; border-radius: 4px; color: #3d7950; background: #f0f8f0; font: 8px var(--mono); letter-spacing: .05em; }
